#include <vector>

using namespace std;

class Solution {
public:
    vector<vector<int>> shiftGrid(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<int> flat;
        for (auto& row : grid)
            for (int val : row)
                flat.push_back(val);
        k = k % (m * n);
        rotate(flat.rbegin(), flat.rbegin() + k, flat.rend());
        vector<vector<int>> res(m, vector<int>(n));
        for (int i = 0; i < m * n; ++i)
            res[i / n][i % n] = flat[i];
        return res;
    }
};
